package mix.client.mixui.management.nanovg.font;

/**
 * 图标字形的<b>墨迹盒中线</b>表，用来把图标精确摆到方框正中心。
 *
 * <p>为什么要写死一张表：{@code nvgTextBounds} 走的是 stb_truetype 的位图盒，给的是
 * 像素对齐后的近似值，而且在带 {@code NVG_ALIGN_MIDDLE} 时会把行高偏移一并算进去。
 * 拿它反解 pen 坐标时误差不是常量 —— 每个字形各自不同，于是观感就是「有的图标偏、
 * 有的不偏」。图标本来就是纯几何图形，墨迹盒的真实值完全可以在编译期从 TTF 的 glyf
 * 表里直接读出，运行时只剩一次二分查表 + 一次乘加，既准又快，也不受 NanoVG 内部
 * 实现（字体栈版本、像素对齐开关）变化的影响。</p>
 *
 * <p>表里存两个数：墨迹盒中心相对 pen 原点的千分之一 em 值。{@code ax} 向右为正，
 * {@code ay} <b>向上为正</b>（与字体坐标系同向）。摆放公式：
 * {@code penX = centerX - ax * size / 1000}、{@code penY = centerY + ay * size / 1000}，
 * 因为屏幕 y 轴朝下而字体 y 轴朝上，两个轴的方向是反的。</p>
 *
 * <p>两套字体从 TTF 直接读出的实测值：</p>
 * <ul>
 *   <li>MaterialSymbolsRounded：unitsPerEm 960，hhea 1056 / -96，行高中线 -0.500 em；
 *       墨迹中心中位数 <b>0.500 em</b> —— 这套图标本来就是按行高中线居中的，只有个别
 *       字形（MINIMIZE / MAXIMIZE、信号格、对齐类）故意偏出 0.02~0.33 em。</li>
 *   <li>Icon.ttf（7.1.2 自制那套）：unitsPerEm 1024，hhea 827 / -212，行高中线 -0.3003 em；
 *       墨迹中心中位数 <b>0.2998 em</b>，同样正好压在行高中线上。</li>
 * </ul>
 *
 * <p>所以「两套字体混用时一个偏上一个偏下」本身不是字体设计问题：旧代码按 {@code size / 2}
 * 手工偏移用的是<b>字号的一半</b>而不是<b>行高中线</b>，两套字体的行高中线相差 0.2 em，
 * 在 48px 的图标 tile 上就是 4.8px 的固定下沉。查表法把这一项彻底消掉。</p>
 *
 * <p><b>为什么数据是编码串而不是数组字面量</b>：3396 条记录写成 {@code int[]} 字面量会让
 * {@code <clinit>} 超过 JVM 的 64KB 单方法上限，javac 直接报「代码过长」。改成两段
 * 十六进制串、在静态块里解码，字节码只剩一个循环。</p>
 */
public final class IconInk {

	/** 兜底：Material Symbols 的墨迹中心（千分之一 em）。 */
	private static final int[] DEFAULTS_MATERIAL = new int[] { 500, 500 };

	/** 兜底：Icon.ttf 的墨迹中心（千分之一 em）。 */
	private static final int[] DEFAULTS_LEGACY = new int[] { 500, 300 };

	/**
	 * Material Symbols 的记录串：每条 14 个十六进制字符，
	 * 「码点 6 位」+「墨迹中心 x + 1000，4 位」+「墨迹中心 y + 1000，4 位」，按码点升序。
	 */
	private static final String MATERIAL_DATA =
			""
			+ ""
			+ ""
			+ ""
			+ ""
			+ ""
			+ "";

	/** Icon.ttf 的记录串，编码同上。 */
	private static final String LEGACY_DATA =
			""
			+ "";

	private static final int[] MATERIAL_CP;
	private static final short[] MATERIAL_AX;
	private static final short[] MATERIAL_AY;

	private static final int[] LEGACY_CP;
	private static final short[] LEGACY_AX;
	private static final short[] LEGACY_AY;

	static {

		int[] matCp = new int[MATERIAL_DATA.length() / 14];
		short[] matAx = new short[matCp.length];
		short[] matAy = new short[matCp.length];

		for (int i = 0; i < matCp.length; i++) {

			int base = i * 14;

			matCp[i] = (int) Long.parseLong(MATERIAL_DATA.substring(base, base + 6), 16);
			matAx[i] = (short) (Integer.parseInt(MATERIAL_DATA.substring(base + 6, base + 10), 16) - 1000);
			matAy[i] = (short) (Integer.parseInt(MATERIAL_DATA.substring(base + 10, base + 14), 16) - 1000);
		}

		MATERIAL_CP = matCp;
		MATERIAL_AX = matAx;
		MATERIAL_AY = matAy;

		int[] legCp = new int[LEGACY_DATA.length() / 14];
		short[] legAx = new short[legCp.length];
		short[] legAy = new short[legCp.length];

		for (int i = 0; i < legCp.length; i++) {

			int base = i * 14;

			legCp[i] = (int) Long.parseLong(LEGACY_DATA.substring(base, base + 6), 16);
			legAx[i] = (short) (Integer.parseInt(LEGACY_DATA.substring(base + 6, base + 10), 16) - 1000);
			legAy[i] = (short) (Integer.parseInt(LEGACY_DATA.substring(base + 10, base + 14), 16) - 1000);
		}

		LEGACY_CP = legCp;
		LEGACY_AX = legAx;
		LEGACY_AY = legAy;
	}

	private IconInk() {
	}

	/** 这个字体名是不是图标字体（只有图标字体才吃这张表）。 */
	public static boolean isIconFont(String fontName) {

		return "material".equals(fontName) || "icon".equals(fontName);
	}

	/**
	 * 算出让 {@code text} 的墨迹盒中心正好落在 {@code (centerX, centerY)} 上的 pen 坐标。
	 *
	 * @return {@code {penX, penY}}；字体不是图标字体、或文本为空时返回 {@code null}，
	 *         调用方自行回退到按文本度量。
	 */
	public static float[] penFor(String text, String fontName, float centerX, float centerY, float size) {

		if (text == null || text.isEmpty() || fontName == null) {
			return null;
		}

		boolean material = "material".equals(fontName);
		boolean legacy = "icon".equals(fontName);

		if (!material && !legacy) {
			return null;
		}

		int cp = text.codePointAt(0);
		int ax = material ? DEFAULTS_MATERIAL[0] : DEFAULTS_LEGACY[0];
		int ay = material ? DEFAULTS_MATERIAL[1] : DEFAULTS_LEGACY[1];

		if (material) {

			int idx = indexOf(MATERIAL_CP, cp);

			if (idx >= 0) {
				ax = MATERIAL_AX[idx];
				ay = MATERIAL_AY[idx];
			}
		} else {

			int idx = indexOf(LEGACY_CP, cp);

			if (idx >= 0) {
				ax = LEGACY_AX[idx];
				ay = LEGACY_AY[idx];
			}
		}

		float perEm = size / 1000F;

		// 屏幕 y 朝下、字体 y 朝上，所以垂直方向要加不要减。
		return new float[] { centerX - (ax * perEm), centerY + (ay * perEm) };
	}

	private static int indexOf(int[] sorted, int key) {

		int lo = 0;
		int hi = sorted.length - 1;

		while (lo <= hi) {

			int mid = (lo + hi) >>> 1;
			int value = sorted[mid];

			if (value < key) {
				lo = mid + 1;
			} else if (value > key) {
				hi = mid - 1;
			} else {
				return mid;
			}
		}

		return -1;
	}
}
